#!/usr/bin/env python3
"""
Round 138b (culprits), 2 October 2026. Needs round 137b.

The Living Planet populations as map tiles with boxes; key filters inside groups.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 138b (2 October)\n\nNeeds round 137b. Tiles patch round138b_tiles.py beside it. No app.js?v= bump.\n\n- lpi_populations is map tiles with boxes (route pmtiles), not one file: the\n  2024 public Living Planet Database (uploaded 2 October) is 35,996\n  populations, 46 MB as one GeoJSON, too heavy for a browser. Tiles\n  lpi_populations.py writes tiles/lpi_populations.pmtiles (class, system,\n  name, change, last year counted) and each record whole to\n  lpi/lpi_populations/<hh>.json.gz (env_enforcement.write_layer). It skips the\n  Mac copies the zip carries (__MACOSX/._*.csv) and reads the BOM in the\n  header. Coloured by system, change or class; key filters by kind of animal\n  (LPI_CLASSES, plain words) and system.\n- Key filters now draw for rows inside groups too (they were drawn only for\n  the main list's rows).\n- Tested on the real download: 35,996 populations, all with a position.\n\n"]


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round138b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 137b" not in h.read_text(encoding="utf-8"):
        sys.exit("round138b: round 137b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round138b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round138b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round138b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
